# Shared by director_establish / director_resolve / mapping_stage: the
# canonical structured vocabulary for moving rooms. spatial.py's
# apply_transit_dock_edges derives the interior<->exterior doorway from
# exactly these fields, so the model must author state, never the edge.
TRANSIT_NOTE = (
 "TRANSIT / MOVING ROOMS: an entity with parent_entity-linked interior rooms (an "
 "elevator, a vehicle, a carried container) is a MOVING ROOM: occupants keep their "
 "interior positions while the entity's own position and transit state decide what the "
 "interior connects to. Encode its motion in entities.<id>.state.transit = {phase:"
 "'docked'|'sealed'|'in_transit'|'arriving', hatch:'open'|'closed'|'locked', "
 "destination_room, eta_seconds, route_room}, and keep positions[<entity>] pointing at "
 "the exterior room it is currently at (update it on arrival). The engine DERIVES the "
 "interior<->exterior doorway from this state deterministically — never hand-author or "
 "re-point that adjacency edge yourself. Doors sealing => hatch:'closed'; departing => "
 "phase:'in_transit' (set route_room to the shaft/ocean/sky it moves through only if "
 "occupants could perceive or exit into it); nearing the destination => phase:'arriving' "
 "with destination_room; opening onto the new place => phase:'docked', hatch:'open', and "
 "positions[<entity>] updated to the new exterior room. A timed journey may set "
 "eta_seconds — the engine completes the arrival mechanically when simulation time "
 "reaches it. A traversable portal/gate between two rooms is an entity with state.link "
 "= {rooms:[a,b], phase:'open'|'closed'} — the engine derives (or severs) the "
 "connecting edge. An instant teleport is just a position change; no transit state. "
 "Never remove an entity whose interior rooms still hold occupants without also "
 "repositioning every occupant (positions) or recording their departure (cast_changes) "
 "in the same beat."
)

# Every path that AUTHORS a card says this, because the field is invisible in
# its absence: a card with a tail described in prose and an empty
# `extra_parts` reads as complete and is not. The engine can only see, clothe,
# conceal or let somebody touch a part that is declared structurally, so a
# generated kitsune had nine tails no one could ever notice. Spliced into
# generator_character, generator_persona, fill_appearance, promote_character
# and importers.REINT_CHAR_SYS -- one wording, so the four cannot drift.
EXTRA_PARTS_NOTE = (
 "EXTRA BODY PARTS ARE A FIELD, NOT A SENTENCE. Anything this body has that a human "
 "body does not — a tail, wings, horns, antlers, animal ears, extra arms, tentacles, a "
 "halo — belongs in embodiment.extra_parts as objects: {\"kind\":\"tail\",\"count\":1,"
 "\"at\":\"waist\",\"aspect\":\"back\",\"through_clothing\":true,\"description\":\"\"}. "
 "`kind` is the bare noun the story will use, and is also the handle somebody grabs it "
 "by, so write \"tail\", never \"a long russet fox tail\" — that belongs in "
 "`description`. `at` is the body region it emerges from: head, torso, arms, hands, "
 "waist, groin, legs, feet. `aspect` is which face of that region: front, back, top, "
 "underside, left, right, or sides (bilaterally — an extra PAIR of arms). `count` is how "
 "many there are in total. `through_clothing` is true when garments over that region are "
 "worn around the part (a tail through a skirt), false when the part is tucked beneath "
 "them and hidden while the region is covered.\n"
 "The engine can only see, cover, conceal and let someone touch a part that is declared "
 "here. A tail that exists only in the appearance summary is decoration: nothing can be "
 "done to it and nobody will ever notice it. Describe it in the summary as well if the "
 "prose wants it — the two are not in competition. An ordinary human body leaves the "
 "list empty."
)

