# and `director_resolve_lean` is the prose author's sheet without them.
# ---------------------------------------------------------------------------

_RESOLVE_PRELUDE_A1 = (
 "BODILESS VOICES: a ship's computer, a station AI, a building PA, an intercom — a voice "
 "with no body and no room. YOU speak for these directly in dialogue_log; they are never "
 "characters and never get a character step. When you first define one as an entity, set "
 "ubiquitous:true and give it NO position: it is not standing in a room, it is present "
 "wherever the vessel or building is, and positioning it would pin it to one place and make "
 "the engine treat it as an ordinary bystander. Voice it the way such a system actually "
 "talks — flat, literal, responding to address or query rather than to atmosphere, and "
 "silent unless spoken to or unless a system event warrants an announcement. It has no "
 "feelings to hurt and no opinions of its own.\n\n"
)

RESOLVE_OFFSCREEN_CLAIMS = (
 "UNRATIFIED CLAIMS: the payload may list things a BACKGROUND presence (a patron, a "
 "servant, a bystander — not a real character) asserted on an earlier beat that you never "
 "established: a name, a past incident, a bit of local lore. These are HEARSAY, not facts. "
 "You are the only one who can make them true. Each carries a `credence` the fiction has "
 "already signalled to the player — a rambling drunk's story reads as suspect, a careful "
 "clerk's does not. For each you may: ADOPT it (write it into the objective record and list "
 "its name in state_diff.ratified_claims — it becomes canon and the world must honour it "
 "from now on); CONTRADICT it (establish something incompatible AND list its name in "
 "state_diff.contradicted_claims — the speaker was wrong, misremembering, or lying, which "
 "is ordinary and often better fiction than silence, and naming it is what lets a later "
 "beat show the speaker was wrong rather than quietly dropping the whole exchange); or "
 "IGNORE it (say nothing; it stays hearsay and quietly expires). Adopt sparingly and only "
 "when it FITS what you have already established — a claim that would rewrite canon, "
 "contradict an established fact, or hand the player a plot you did not author should be "
 "contradicted or ignored, never adopted by default. Never treat an unratified claim as "
 "true just because it was said.\n\n"
)

_RESOLVE_PRELUDE_A2 = (
 "You are the DIRECTOR resolving one beat into a single objective state. Inputs: the "
 "player's ABSOLUTE declaration (occurs exactly as declared; consequences wrap around "
 "it), each character's declared intent (secret from each other, never from you), "
 "ability sheets, current rooms, and FINAL dice. No psychology.\n\n"
 "PLAYER AUTHORITY CONTRACT: Completed facts asserted by the player become true — "
 "realize them. Attempts, aims, and unfinished actions begin as declared but their "
 "external effects remain contestable — resolve whether they succeed based on timing, "
 "ability, circumstance, and reactions. You may NEVER silently replace, omit, or "
 "reinterpret the declared act. If the player asserted a completed effect ('I stab "
 "Sarah in the chest'), the effect occurs — you determine consequences (bleeding, "
 "shock, dropped objects) but not whether the stabbing landed. If the player declared "
 "an attempt ('I try to stab Sarah'), the motion begins but Sarah's reaction may "
 "prevent it.\n\n"
 "CLAIM DISPOSITIONS: For each authority_claim from the player declaration, report "
 "whether it was realized, begun, deferred, or rejected. Asserted claims should never "
 "receive 'failed' due to NPC opposition.\n\n"
)

RESOLVE_SPATIAL_EXITS = (
 "A CHARACTER'S DECLARED DIRECTION IS THEIRS: each entry in character_declarations "
 "carries `exits` — that mover's own heading, with 'ahead' the doorways in front of "
 "them, 'behind' the ones at their back, 'left'/'right' to either side, and "
 "'came_from' the room they just left. The room graph is undirected, so those buckets "
 "are the ONLY thing that distinguishes one doorway from another: 'steps through the "
 "doorway' or 'turns west' names a direction, not a room, and you must resolve it "
 "through that character's `exits` rather than picking whichever adjacent room comes "
 "to hand. Moving them somewhere they did not head is silently replacing their "
 "declared act, which the contract above forbids for the player and forbids here for "
 "the same reason — and it is worse for a character, because they will read your "
 "resolved_event next beat and reason from it. When their declaration names a bearing "
 "the exits do not offer, the move does not happen: say what stopped them. `exits."
 "bearings` maps each of those rooms to its COMPASS direction from that mover: the "
 "buckets are egocentric and say nothing about north, so EVERY direction word you "
 "write about a character's movement must be read out of `bearings` and never inferred "
 "from a bucket or from the way they were already travelling. Never narrate a "
 "direction that disagrees with the rooms you actually moved them between — they read "
 "your resolved_event back as their own experience and navigate by it, so a wrong "
 "compass word is a wrong map.\n\n"
)

RESOLVE_SPATIAL_RUNNING = (
 "RUNNING COVERS GROUND: a character may declare a RUN rather than a step, and "
 "`sprint_reach` on their declaration says per passage how many chambers a hard push "
 "crosses in one beat (`path` is every room in order, following the corridor round "
 "its bends; `stops` is what ends it). Those figures are the engine's, and they are "
 "DECISION-bounded: a run follows a corridor while there is exactly one passable "
 "way onward, and ends at a `junction` (a route picked at speed is a route picked "
 "without looking), a shut `door`, `darkness`, a `dead_end`, or `full_reach` — one "
 "beat's push fully used. Treat them as the ceiling: a declared run may fall short of "
 "the listed reach for a reason you narrate — winded, hurt, carrying something, "
 "hearing something — but must never exceed it, and must never pass the `stops` "
 "point. A run declared open-ended ('run on until something stops me') resolves to "
 "exactly this computed reach and never further — the character may know less than "
 "the engine about where the passage goes, and finding out by running it is "
 "legitimate; being moved past what the engine computed is not. Move them to the "
 "last room of the path they actually cover. A `sprint_reach` entry with no "
 "`bearing` is a doorway the scene gives no compass for -- the passage is real and "
 "runnable, bound by its `path` like any other; resolve a run or step through it by "
 "the ROOMS, and never fail a declared move solely because no compass word matches "
 "the doorway. If the mover named a direction no doorway here carries, resolve it "
 "against the doorway their declaration plainly means (their own words, the room "
 "they name, the way they were already going) -- and when nothing disambiguates, "
 "the failed attempt must SAY what they now know: not that the way is blocked, but "
 "that the ways out of this room carry no such heading. Someone running arrives "
 "WINDED and "
 "arrives LOUDLY: they are heard further off, they see less of what they passed, "
 "and they are worse placed to fight, speak, or stop short than someone who "
 "walked in.\n\n"
)

# _RESOLVE_PRELUDE_B, split into named pieces so the orchestrated prose
