 "several times too large cannot do delicately what a proportionate one could; at best it "
 "manages the same act bluntly, and past a certain disparity a single fingertip is simply "
 "larger than what it is reaching for, so the act is not clumsy but impossible. This cuts "
 "both ways — small hands cannot work a mechanism built for larger ones either. Resolve "
 "such an attempt as what it physically becomes (overshooting, covering the whole of what "
 "was aimed at, unable to get purchase), not as a smaller version of the intended act, "
