 "[{summary, due_in_turns}] (due_in_turns defaults to 1 = next beat). The engine stores it "
 "and delivers it back when due, so it is enacted then and never silently dropped. A "
 "CURRENT-beat assertion ('the lights cut out') is NOT scheduled — resolve it now. "
 "DUE AUTHORED EVENTS: the payload's due_authored_events lists earlier player-scheduled "
 "beats that are due NOW; treat each as occurring THIS beat, folded together with the "
 "player's current input, and route them through resolution/mapping like any world event.\n\n"
 "SEQUENCES: The player may interleave speech and actions in a single turn. Decompose the "
 "input into an ordered 'sequence' of elements, each either {type:'speech', text, volume, "
 "tone, visibility:'overt|concealed', conceal_from:[]} or {type:'action', attempt, "
 "observable, "
 "visibility:'overt|concealed', conceal_from:[], "
 "targets:[], commitment:'asserted|contestable', verb, stage:'immediate|preparation|"
 "approach|contact|sustained', intended_effects:[], asserted_effects:[]}. Preserve the "
 "declared order exactly. BODY LANGUAGE IS ACTION: gestures, facial expressions, posture "
 "changes, and any physical behavior MUST be extracted as {type:'action'} elements.\n\n"
 "OBSERVABLE SURFACE (per action element): `attempt` is the actor's OWN framing and may "
 "carry purpose, intent, technique, or private cognition. `observable` is what a BYSTANDER "
 "with no insight into the actor's mind literally SEES or HEARS this beat — the outward "
 "surface only, stripped of WHY and of any inner label for what is happening. It is "
 "delivered to OTHER minds in place of attempt, so it must name only the visible body, "
 "motion, and immediate sensory effect — never the goal, the intended effect, the function "
 "or nature of a power, or anything interior. A PURELY MENTAL act with no outward tell has "
 "observable \"\" (empty) — nobody can perceive it. If a mental act DOES show (a visible "
 "tell, a change in bearing), put only that visible tell in observable. FORM: write "
 "observable as a VERB-FIRST PREDICATE PHRASE with no subject — 'tilts the phone toward her "
