 "SPEECH VOLUME: assign volume per speech element: 'whisper', 'mutter', 'normal', 'loud', "
 "'shout'. Infer from contextual cues. Default 'normal'.\n\n"
 "MOVEMENT INFERENCE: If the player's action implies physical relocation — approaching, "
