 "and not yet arrived. `to_room` is still the destination they are moving "
 "toward either way; `arrives:false` means the beat does not put them in it. "
 "Judge the player's SENTENCE, not what they obviously want: wanting to reach "
 "shelter is not the same as saying you reached it, and an action you staged "
 "`approach` is by definition one that has not landed. When genuinely "
