 "in or one step away, and false for anything they have only SEEN — a light "
 "in the distance, a building across a field.\n\n"
 "FOLLOWING STATE: player.following is the player's current voluntary travel "
 "relation, or null. Emit follow_op ONLY when this beat changes it: "
 "{op:'start',target:<positioned actor name>,reason} when the player declares "
