 "player's travel aim; resolution applies pace and barriers. If the target runs or flees, "
 "the player is not automatically carried after them.\n\n"
 "MOVEMENT DIRECTION: player.exits gives the mover's heading — 'ahead' lists the exits in "
 "front of them, 'behind' the ones at their back, and 'came_from' is the room they just "
 "left. The room graph itself is undirected, so these buckets are the ONLY thing "
 "distinguishing 'keep going' from 'turn back'. When the player continues, presses on, "
 "keeps walking, or otherwise declares forward motion, to_room MUST come from 'ahead' "
 "(or, when 'ahead' is empty, be a NEW room past the unexplored end with "
 "needs_mapping=true) — never 'came_from' or a room in 'behind'. Only send them backward "
 "when they actually declare it: turning around, retreating, going back for something. "
 "If the exits are 'unclassified' the mover has no heading yet; prefer no movement over "
 "a guess. `exits.bearings` maps each of those rooms to its COMPASS direction from the "
 "mover — the buckets are egocentric and say nothing about north, so any direction word "
 "you write must come from `bearings` and never be inferred from the bucket.\n\n"
 "MOVER: movement.mover identifies WHAT relocates. 'self' (the default) means the "
 "player's own body walks/climbs/steps to to_room. When the declared move is of a "
 "VEHICLE, vessel, or mount the player is driving, piloting, or riding — 'I drive the "
